      {category:"Penulisan Kanji",instruction:"＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"こどもは <u>まんが</u>が すきです。",options:["漫画","道具","本棚","声"],answer:0,explanation:"まんが ditulis 漫画, berarti komik.",material:"Bab 26–30 · Mondai 2 No.16",srsId:"kanji:漫画"},
      {category:"Penulisan Kanji",instruction:"＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"この かしゅは とても <u>にんき</u>です。",options:["人気","経験","給料","会話"],answer:0,explanation:"にんき ditulis 人気, berarti populer.",material:"Bab 26–30 · Mondai 2 No.17",srsId:"kanji:人気"},
      {category:"Penulisan Kanji",instruction:"＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"でんきが <u>きえました</u>。",options:["消えました","壊れました","汚れました","閉まりました"],answer:0,explanation:"きえました ditulis 消えました, berarti padam/mati.",material:"Bab 26–30 · Mondai 2 No.18",srsId:"kanji:消えます"},
      {category:"Penulisan Kanji",instruction:"＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"<u>さいふ</u>を おとしました。",options:["財布","袋","枝","壁"],answer:0,explanation:"さいふ ditulis 財布, berarti dompet.",material:"Bab 26–30 · Mondai 2 No.19",srsId:"kanji:財布"},
      {category:"Penulisan Kanji",instruction:"＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"つくえを <u>かたづけます</u>。",options:["片づけます","並べます","飾ります","植えます"],answer:0,explanation:"かたづけます ditulis 片づけます, berarti membereskan.",material:"Bab 26–30 · Mondai 2 No.20",srsId:"kanji:片づけます"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"どうして がっこうを やすんだ（　）ですか。",options:["ん","と","ば","のに"],answer:0,explanation:"んですか dipakai untuk meminta penjelasan atau alasan.",material:"Bab 26–30 · Mondai 3 No.21",srsId:"materi:book2:0:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"はやく ね（　）ほうが いいです。",options:["た","ます","ない","て"],answer:0,explanation:"Vた ほうがいいです dipakai untuk memberi saran/anjuran.",material:"Bab 26–30 · Mondai 3 No.22",srsId:"materi:book2:1:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"いえに かえっ（　）、てがみが ありました。",options:["たら","ても","と","なら"],answer:0,explanation:"Vたら dapat menyatakan penemuan sesuatu setelah suatu tindakan dilakukan.",material:"Bab 26–30 · Mondai 3 No.23",srsId:"materi:book2:2:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"しごとの（　）が あります。",options:["けいけん","きゅうりょう","にんき","かいわ"],answer:0,explanation:"けいけん berarti pengalaman: “Saya punya pengalaman kerja.”",material:"Bab 26–30 · Mondai 3 No.24",srsId:"materi:book2:2:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"まどが あいて（　）。",options:["います","あります","です","ちがいます"],answer:0,explanation:"自動詞 (kata kerja intransitif) + ています menunjukkan keadaan hasil suatu tindakan.",material:"Bab 26–30 · Mondai 3 No.25",srsId:"materi:book2:3:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"でんきが ついて（　）。",options:["います","あります","です","ちがいます"],answer:0,explanation:"つきます (menyala) + ています menunjukkan keadaan lampu sedang menyala.",material:"Bab 26–30 · Mondai 3 No.26",srsId:"materi:book2:3:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"パーティーの まえに へやを そうじし（　）。",options:["ておきます","ています","てあります","てみます"],answer:0,explanation:"Vて おきます menyatakan melakukan persiapan sebelumnya.",material:"Bab 26–30 · Mondai 3 No.27",srsId:"materi:book2:4:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"つかった どうぐは もとの ところに もどし（　）。",options:["ておきます","ています","てあります","てみます"],answer:0,explanation:"Vて おきます dipakai untuk tindakan persiapan agar nanti lebih mudah.",material:"Bab 26–30 · Mondai 3 No.28",srsId:"materi:book2:4:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"きぶんが（　）から、やすみます。",options:["わるい","いい","つごうがいい","かんたんな"],answer:0,explanation:"きぶんがわるい berarti tidak enak badan, sehingga perlu istirahat.",material:"Bab 26–30 · Mondai 3 No.29",srsId:"materi:book2:0:0"},
      {category:"Kosakata",instruction:"（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"としょかんで ほんが（　）。",options:["みえます","みます","きこえます","ききます"],answer:0,explanation:"みえます dipakai untuk sesuatu yang terlihat dengan sendirinya, berbeda dari みます (melihat dengan sengaja).",material:"Bab 26–30 · Mondai 3 No.30",srsId:"materi:book2:1:0"},
      {category:"Parafrasa",instruction:"＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"どうして がっこうを やすんだんですか。",options:["どうして がっこうを やすみましたか。","がっこうを やすみましょう。","がっこうは やすみです。","がっこうへ いきたいです。"],answer:0,explanation:"んですか menambahkan nuansa meminta penjelasan, tapi maknanya tetap sama dengan pertanyaan biasa.",material:"Bab 26–30 · Mondai 4 No.31",srsId:"materi:book2:0:0"},
      {category:"Parafrasa",instruction:"＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"つかれましたから、はやく ねた ほうが いいです。",options:["はやく ねる ほうが いいと おもいます。","おそく ねる ほうが いいと おもいます。","ねない ほうが いいと おもいます。","はやく おきる ほうが いいと おもいます。"],answer:0,explanation:"Vた ほうがいいです dan V辞書形 ほうがいいと おもいます sama-sama menyatakan saran.",material:"Bab 26–30 · Mondai 4 No.32",srsId:"materi:book2:1:0"},
      {category:"Parafrasa",instruction:"＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"いえに かえったら、てがみが ありました。",options:["いえに かえった とき、てがみが ありました。","いえに かえる まえに、てがみを かきました。","いえに かえっても、てがみは ありませんでした。","てがみを かいてから、いえに かえりました。"],answer:0,explanation:"Vたら (penemuan) dan Vた とき (saat itu) sama-sama menyatakan keadaan yang ditemukan pada waktu tertentu.",material:"Bab 26–30 · Mondai 4 No.33",srsId:"materi:book2:2:0"},
      {category:"Parafrasa",instruction:"＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"でんきが ついています。",options:["だれかが でんきを つけました。","だれかが でんきを けしました。","へやには だれも いません。","でんきは まだ つけていません。"],answer:0,explanation:"でんきが ついています (keadaan menyala) menunjukkan bahwa sebelumnya seseorang telah menyalakannya.",material:"Bab 26–30 · Mondai 4 No.34",srsId:"materi:book2:3:0"},
      {category:"Parafrasa",instruction:"＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。",html:"パーティーの まえに へやを そうじしておきます。",options:["パーティーの じゅんびで へやを そうじします。","パーティーの あとで へやを そうじします。","パーティーが おわったら、へやを そうじします。","へやを そうじしなくても いいです。"],answer:0,explanation:"Vて おきます (persiapan sebelumnya) sepadan dengan melakukan sesuatu sebagai じゅんび (persiapan).",material:"Bab 26–30 · Mondai 4 No.35",srsId:"materi:book2:4:0"}
